package com.student.controller;
import com.student.dao.*; import com.student.model.Student; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class AddStudentServlet extends HttpServlet{private final CourseDAO courses=new CourseDAO();private final StudentDAO students=new StudentDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}load(req);req.getRequestDispatcher("/add-student.jsp").forward(req,resp);}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{Student s=new Student();s.setFirstName(req.getParameter("firstName"));s.setLastName(req.getParameter("lastName"));s.setEmail(req.getParameter("email"));s.setPhone(req.getParameter("phone"));s.setGender(req.getParameter("gender"));s.setDepartment(req.getParameter("department"));s.setCity(req.getParameter("city"));s.setCourseId(Integer.parseInt(req.getParameter("courseId")));s.setStatus(req.getParameter("status"));students.save(s);resp.sendRedirect("students");}catch(Exception e){req.setAttribute("error","Could not save student. Please check the entered details.");load(req);req.getRequestDispatcher("/add-student.jsp").forward(req,resp);}}private void load(HttpServletRequest req)throws ServletException{try{req.setAttribute("courses",courses.findActiveCourses());}catch(Exception e){throw new ServletException(e);}}}
